def write(name, data):
    with (ROOT/name).open('w',encoding='utf-8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)
write('bibliography_featured.csv',rows)
write('sources_featured.csv',sources)
print(f'Wrote {len(rows)} featured/context/bridge records and {len(sources)} source records')
